import { z } from "zod";
import { ProductIdSchema, type ProductId } from "./catalog.ts";

/**
 * Account-wide achievements and referrals.
 *
 * Authority lives in the provider ledger (Convex). The public ATProto record
 * written to the account's PDS is a portable display copy only: the account
 * owner can edit it, so nothing may infer an award or a reward from it.
 */

export const ACHIEVEMENT_COLLECTION = "info.notorganic.achievement";
/** Granular ATProto OAuth permissions needed to publish an achievement record. */
export const ACHIEVEMENT_PUBLISH_SCOPES = [
  `repo:${ACHIEVEMENT_COLLECTION}`,
  "blob:image/png",
] as const;

export const AchievementKeySchema = z.string().regex(/^[a-z0-9][a-z0-9-]{1,62}$/, "Use 2–63 lowercase letters, digits or hyphens.");
/** Achievement assets are served by the portal; a PDS blob is created from the same bytes on publish. */
export const AchievementAssetPathSchema = z.string().regex(/^\/(achievements|brand)\/[a-z0-9][a-z0-9/-]{0,120}\.png$/, "Use a PNG under /achievements/ or /brand/.");
export const ReferralCodeSchema = z.string().regex(/^[A-Za-z0-9]{10,32}$/);
export const ReferralEventSchema = z.string().regex(/^[a-z0-9][a-z0-9_.-]{1,62}$/);

export const AchievementAwardInputSchema = z.object({ achievement: AchievementKeySchema }).strict();
export const ReferralClaimInputSchema = z.object({ code: ReferralCodeSchema }).strict();
export const ReferralQualifyInputSchema = z.object({ event: ReferralEventSchema }).strict();
export const ReferralCodeInputSchema = z.object({ application: ProductIdSchema }).strict();

/** Admin policy. Defaults are zero: no promotional value exists until an operator sets it. */
export const AchievementDefinitionInputSchema = z.object({
  application: ProductIdSchema,
  key: AchievementKeySchema,
  title: z.string().trim().min(2).max(80),
  description: z.string().trim().min(2).max(300),
  asset_path: AchievementAssetPathSchema,
  reward_micros: z.number().int().min(0).max(100_000_000).default(0),
  active: z.boolean().default(true),
}).strict();
export const ReferralPolicyInputSchema = z.object({
  application: ProductIdSchema,
  qualifying_event: ReferralEventSchema,
  referrer_reward_micros: z.number().int().min(0).max(100_000_000).default(0),
  referee_reward_micros: z.number().int().min(0).max(100_000_000).default(0),
  active: z.boolean().default(true),
}).strict();

export type AchievementPublicationState = "unpublished" | "published" | "failed";
export type RewardState = "none" | "issued";

export interface AchievementAward {
  object: "achievement_award";
  id: string;
  application: ProductId;
  achievement: string;
  title: string;
  description: string;
  asset_path: string;
  awarded_at: number;
  reward: { state: RewardState; amount_micros: number };
  publication: { state: AchievementPublicationState; uri?: string; cid?: string; record_url?: string; error?: string };
}

export interface AchievementDefinitionView {
  application: ProductId;
  key: string;
  title: string;
  description: string;
  asset_path: string;
  reward_micros: number;
}

/** Operator view of the setup, including inactive entries. Never shown to customers. */
export interface AchievementAdminCatalog {
  definitions: Array<AchievementDefinitionView & { active: boolean; updated_at: number }>;
  policies: Array<{ application: ProductId; qualifying_event: string; referrer_reward_micros: number; referee_reward_micros: number; active: boolean; updated_at: number }>;
}

export interface ReferralClaim {
  object: "referral_claim";
