      .query("accountExports")
      .withIndex("by_ownerId", (q) => q.eq("ownerId", identity.tokenIdentifier))
      .order("desc")
      .first();
    if (!row) return null;
    return {
      id: row._id,
      status: row.status,
      createdAt: row.createdAt,
      completedAt: row.completedAt ?? null,
