      .paginate(paginationOpts);
    return {
      page: result.page,
      continueCursor: result.continueCursor,
      isDone: result.isDone,
    };
  },
});

export const finish = internalMutation({
  args: {
    exportId: v.id("accountExports"),
    storageId: v.id("_storage"),
    bytes: v.number(),
    rowCount: v.number(),
