/* ── Identity helpers ───────────────────────────────────────────── */

async function requireIdentity(ctx: {
  auth: { getUserIdentity: () => Promise<{ tokenIdentifier: string } | null> };
}): Promise<string> {
  const id = await ctx.auth.getUserIdentity();
  if (!id) throw new Error("Not signed in");
  return id.tokenIdentifier;
}

/* ── Briefs ──────────────────────────────────────────────────────── */

export const getBrief = query({
  args: { folioId: v.optional(v.string()) },
export const putFolioContent = mutation({
  args: {
    folioId: v.string(),
    html: v.string(),
    format: v.optional(v.union(v.literal("html"), v.literal("typst"))),
    typstSource: v.optional(v.string()),
    kit: v.optional(
      v.union(
        v.literal("essay"),
        v.literal("technical"),
        v.literal("paper"),
        v.literal("play"),
      ),
    ),
  },
  returns: v.id("folioContent"),
  handler: async (ctx, { folioId, html, format, typstSource, kit }) => {
    const userId = await requireIdentity(ctx);
    const existing = await ctx.db
      .query("folioContent")
      .withIndex("by_userId_folioId", (q) =>
        q.eq("userId", userId).eq("folioId", folioId),
      )
      .first();
    const now = Date.now();
    if (existing) {
      if (existing.typstSource !== undefined && typstSource === undefined)
        throw new Error(
          "This document uses Typst. Update your client before editing it.",
        );
      await ctx.db.patch(existing._id, {
        html,
        format,
        typstSource,
        kit,
        updatedAt: now,
      });
      return existing._id;
    }
    return await ctx.db.insert("folioContent", {
      userId,
      folioId,
      html,
      format,
      typstSource,
      kit,
      updatedAt: now,
    });
  },
});

