      await ctx.db.insert("integrationTokens", {
        userId: "issuer|writer",
        tokenHash: "secret-hash",
        prefix: "twy_abc",
        name: "CLI",
        createdAt: 1,
      });
      await ctx.db.insert("lixBlobs", {
        userId: "issuer|writer",
        blob: new Uint8Array([1, 2, 3]).buffer,
        updatedAt: 1,
      });
    });

