import { chromium } from "/home/diogenes/Projects/apps/twyne/node_modules/playwright/index.mjs";
const browser = await chromium.launch();
for (const [name, w, h] of [["desktop", 1280, 800], ["phone", 390, 844]]) {
  const page = await browser.newPage({ viewport: { width: w, height: h } });
  await page.route(/\/api\/auth\//, (r) => r.fulfill({ contentType: "application/json", body: "null" }));
  await page.route("**/__seed", (r) => r.fulfill({ contentType: "text/html", body: "<!doctype html><title>seed</title>" }));
  await page.goto("http://localhost:5174/__seed");
  await page.evaluate(async () => {
    const db = await import("/src/utils/idb.ts");
    const now = Date.now(), id = "menu-fixture";
    await db.saveFoliosToIdb([{ id, name: "Menu check", type: "draft", createdAt: now, updatedAt: now }]);
    await db.saveFolioContentToIdb(id, "<p>Hello.</p>");
    await db.saveActiveFolioIdToIdb(id);
    await db.saveMetaToIdb("signin-toast-dismissed", true);
    localStorage.setItem("twyne:editor:view:v1", JSON.stringify({ zenMode: false, compositorOpen: false }));
  });
  await page.goto("http://localhost:5174/editor/");
  const btn = page.getByRole("button", { name: /Open the editor's office/ });
  await btn.waitFor({ timeout: 90000 });
  await page.waitForTimeout(1500);
  await btn.click();
  const panel = page.locator("div.folio.space-y-2").filter({ hasText: "Sign in with your Not Organic" });
  await panel.waitFor();
  const overflow = await panel.evaluate((el) => {
    const box = el.getBoundingClientRect();
    return [...el.querySelectorAll("p,button")].some((n) => n.scrollWidth > n.clientWidth + 1 || n.getBoundingClientRect().right > box.right + 1);
  });
  const box = await panel.boundingBox();
  console.log(name, "overflow:", overflow, "panel:", Math.round(box.x), Math.round(box.width), "viewport", w);
  await panel.screenshot({ path: `/tmp/twyne-shots/menu-${name}.png` });
  await page.close();
}
await browser.close();
EOF
