(TWYNE_DEV_PORT=5174 bun run dev.frontend > /tmp/twyne-dev.log 2>&1 &); for i in $(seq 1 60); do curl -sf -o /dev/null http://localhost:5174/ && break; sleep 1; done; mkdir -p /tmp/sync-perf && cat > /tmp/sync-perf/run.mjs <<'EOF'
import { chromium } from "/home/diogenes/Projects/apps/twyne/node_modules/playwright/index.mjs";
import { writeFileSync } from "node:fs";
const mode = process.argv[2] ?? "sync"; // "sync" | "nosync"
const FOLIOS = +(process.argv[3] ?? 25), KB = +(process.argv[4] ?? 60), NOTES = +(process.argv[5] ?? 40);
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
await page.route(/\/api\/auth\//, (r) => r.fulfill({ contentType: "application/json", body: "null" }));
await page.route("**/__seed", (r) => r.fulfill({ contentType: "text/html", body: "<!doctype html><title>seed</title>" }));
await page.goto("http://localhost:5174/__seed");
await page.evaluate(async ({ FOLIOS, KB, NOTES }) => {
  const db = await import("/src/utils/idb.ts");
  const now = Date.now();
  const para = "<p>" + "The ledger kept its own counsel through the long winter, and the map did not. ".repeat(12) + "</p>";
  const html = para.repeat(Math.ceil((KB * 1024) / para.length));
  const folios = Array.from({ length: FOLIOS }, (_, i) => ({ id: `f${i}`, name: `Piece ${i}`, type: "draft", createdAt: now, updatedAt: now }));
  await db.saveFoliosToIdb(folios);
  for (const f of folios) await db.saveFolioContentToIdb(f.id, html);
  await db.saveActiveFolioIdToIdb("f0");
  await db.saveMetaToIdb("signin-toast-dismissed", true);
  await db.saveMetaToIdb("live-review-enabled", false);
  localStorage.setItem("twyne:editor:view:v1", JSON.stringify({ zenMode: false, compositorOpen: false }));
  window.__seedNotes = NOTES;
}, { FOLIOS, KB, NOTES });
await page.goto("http://localhost:5174/editor/");
const pm = page.locator(".ProseMirror");
await pm.waitFor({ timeout: 120000 });
await page.waitForTimeout(4000);

if (mode === "sync") {
  await page.evaluate(async () => {
    const sync = await import("/src/utils/convex-sync.ts");
    const name = (ref) => { for (const s of Object.getOwnPropertySymbols(ref)) if (String(s).includes("functionName")) return ref[s]; return String(ref); };
    // In-memory stand-in for the Convex deployment. Every write bumps the
    // revision and re-sends the whole pullAll result, as a live query does.
    const server = { syncRevision: 0, briefs: [], legacyBrief: null, legacyBriefUpdatedAt: 0, folios: [], foliosUpdatedAt: 0, folioContent: [], customPersonas: null, customPersonasUpdatedAt: 0, personaNotes: [], personaReplies: [], rubricResults: [], bibliography: [], bibliographyUpdatedAt: 0 };
    const subs = [];
    const stats = (window.__syncStats = { pushes: 0, bytesDown: 0, bytesUp: 0, emitMs: 0 });
    const emit = () => setTimeout(() => {
      const t = performance.now();
      const wire = JSON.stringify(server);
      stats.bytesDown += wire.length;
      for (const cb of subs) cb(JSON.parse(wire));
      stats.emitMs += performance.now() - t;
    }, 30);
    const client = {
      async query(ref) { return name(ref).includes("pullAll") ? JSON.parse(JSON.stringify(server)) : null; },
      async mutation(ref, args) {
        const fn = name(ref);
        if (!fn.includes("pushAll")) return {};
        stats.pushes++; stats.bytesUp += JSON.stringify(args).length;
        for (const row of args.folioContent ?? []) {
          const i = server.folioContent.findIndex((r) => r.folioId === row.folioId);
          const next = { ...row, updatedAt: Date.now() };
          i >= 0 ? (server.folioContent[i] = next) : server.folioContent.push(next);
        }
        if (args.folios) server.folios = args.folios;
        server.syncRevision++;
        emit();
        return { revision: server.syncRevision };
      },
      onUpdate(ref, _args, cb) { subs.push(cb); return () => subs.splice(subs.indexOf(cb), 1); },
    };
    sync.setConvexSyncContext(client, "perf-user");
  });
  await page.waitForTimeout(8000);
}

// Measure: main-thread long tasks and per-key input-to-paint latency.
await page.evaluate(() => {
  window.__long = [];
  new PerformanceObserver((l) => { for (const e of l.getEntries()) window.__long.push(e.duration); }).observe({ type: "longtask", buffered: false });
  window.__lat = [];
  document.addEventListener("keydown", (e) => { const t = e.timeStamp; requestAnimationFrame(() => setTimeout(() => window.__lat.push(performance.now() - t), 0)); }, true);
});
const cdp = await page.context().newCDPSession(page);
await cdp.send("Profiler.enable"); await cdp.send("Profiler.setSamplingInterval", { interval: 500 }); await cdp.send("Profiler.start");
await pm.click();
await page.keyboard.press("Control+End");
const text = " Then the cartographer wrote another line about the river.";
